// Init: valida token/parámetros, normaliza y arma la config.
const inp = $input.first().json || {};
const body = (inp.body && typeof inp.body === 'object') ? inp.body : inp;
const query = inp.query || {};
const headers = inp.headers || {};

const cfg = {
  siteHost: 'kansaisa.sharepoint.com',
  sitePath: '/sites/CentroDeDocumentacion',
  basePath: 'Kansai/Compartidos/Comercial/Ventas Convencionales/Fotos Usados',
  webkaiName: 'WebKai',
  publicBaseUrl: ($env.PUBLIC_BASE_URL || 'http://www.kansai.com.ar/fotos_usados/'),
  ftp: {
    host: ($env.FTP_HOST || 'ftp.kansai.com.ar'),
    port: Number($env.FTP_PORT || 21),
    user: ($env.FTP_USER || 'u917645178.n8nftpkansai'),
    password: ($env.FTP_PASSWORD || ''),
    secure: true,
    dir: ($env.FTP_DIR || '/home/u917645178/domains/kansai.com.ar/public_html/fotos_usados'),
  },
  token: ($env.WEBHOOK_TOKEN || ''),
};

const patente = (body.patente ?? query.patente ?? '').toString().trim().toUpperCase().replace(/\s+/g, '');
const marca = (body.marca ?? query.marca ?? '').toString().trim();
const accion = (body.accion ?? query.accion ?? '').toString().trim().toLowerCase();
const token = (headers['x-api-token'] ?? headers['X-Api-Token'] ?? body.token ?? query.token ?? '').toString();

if (!cfg.publicBaseUrl.endsWith('/')) cfg.publicBaseUrl += '/';
const basePathEnc = cfg.basePath.split('/').map(encodeURIComponent).join('/');

let valid = true;
let mensaje = '';
if (!patente) { valid = false; mensaje = 'Falta el parámetro patente/dominio'; }
else if (accion !== 'subir' && accion !== 'eliminar') { valid = false; mensaje = "El parámetro accion debe ser 'subir' o 'eliminar'"; }
else if (cfg.token && token !== cfg.token) { valid = false; mensaje = 'No autorizado'; }

return [{ json: { _valid: valid, ok: valid ? undefined : false, mensaje, accion, patente, marca, cfg, basePathEnc } }];

// PickPatenteFolder: de los resultados de búsqueda, elige la carpeta de la patente.
const res = ($('GraphSearchPatente').item.json.value) || [];
const initJson = $('Init').item.json;
const patente = initJson.patente;
const marca = initJson.marca;

function norm(s) {
  return (s || '').toString().normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}
function lev(a, b) {
  const m = a.length, n = b.length;
  const d = Array.from({ length: m + 1 }, (_, i) => { const row = new Array(n + 1).fill(0); row[0] = i; return row; });
  for (let j = 0; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return d[m][n];
}
function fuzzy(a, b) {
  a = norm(a); b = norm(b);
  if (!a || !b) return false;
  if (a === b || a.includes(b) || b.includes(a)) return true;
  const dist = lev(a, b);
  return dist <= Math.max(1, Math.floor(Math.max(a.length, b.length) * 0.3));
}

const np = norm(patente);
// Solo carpetas cuyo nombre contiene la patente
let folders = res.filter(it => it.folder && norm(it.name).includes(np));

if (marca) {
  const conMarca = folders.filter(f => {
    const path = (f.parentReference && f.parentReference.path) || '';
    const seg = decodeURIComponent(path).split('/').pop(); // carpeta de marca = último segmento del path padre
    return fuzzy(seg, marca) || fuzzy(path, marca);
  });
  if (conMarca.length) folders = conMarca; // si hay match de marca, priorizar; si no, dejar todas
}

const chosen = folders[0]; // primera encontrada
if (!chosen) {
  return [{ json: { ok: false, accion: 'subir', patente, marca, markdown: '', archivos: [], mensaje: 'No se encontró carpeta con la patente' + (marca ? (' para la marca ' + marca) : '') } }];
}
return [{ json: { ok: true, folderId: chosen.id, folderName: chosen.name } }];

// FindWebKai: dentro de la carpeta de la patente, ubica la subcarpeta WebKai.
const children = ($('GraphListPatenteChildren').item.json.value) || [];
const initJson = $('Init').item.json;
const target = (initJson.cfg.webkaiName || 'WebKai').toLowerCase();

const wk = children.find(c => c.folder && (c.name || '').trim().toLowerCase() === target)
  || children.find(c => c.folder && (c.name || '').trim().toLowerCase().includes(target));

if (!wk) {
  return [{ json: { ok: false, accion: 'subir', patente: initJson.patente, marca: initJson.marca, markdown: '', archivos: [], mensaje: 'No se encontró la carpeta ' + initJson.cfg.webkaiName } }];
}
return [{ json: { ok: true, webkaiId: wk.id } }];

// FtpSubir: descarga las fotos de WebKai y las sube al FTP renombradas.
const ftpLib = require('basic-ftp');
const { Readable } = require('stream');

const initJson = $('Init').item.json;
const cfg = initJson.cfg;
const patente = initJson.patente;
const marca = initJson.marca;
const all = ($('GraphListWebKaiFiles').item.json.value) || [];

// Solo archivos (no subcarpetas), ordenados por nombre
const files = all
  .filter(f => f.file)
  .sort((a, b) => a.name.localeCompare(b.name, 'es', { numeric: true, sensitivity: 'base' }));

if (files.length === 0) {
  return [{ json: { ok: false, accion: 'subir', patente, marca, total: 0, archivos: [], markdown: '', mensaje: 'La carpeta WebKai no tiene fotos' } }];
}

function norm(s) { return (s || '').toString().toUpperCase(); }

const client = new ftpLib.Client(30000);
client.ftp.verbose = false;
const archivos = [];
const markdownLines = [];

try {
  await client.access({
    host: cfg.ftp.host,
    port: cfg.ftp.port,
    user: cfg.ftp.user,
    password: cfg.ftp.password,
    secure: cfg.ftp.secure,
    secureOptions: { rejectUnauthorized: false },
  });
  await client.ensureDir(cfg.ftp.dir);
  await client.cd(cfg.ftp.dir);

  // Borrar sobrantes: todo lo que empiece con la patente
  const existentes = await client.list();
  for (const e of existentes) {
    if (e.isFile && norm(e.name).startsWith(patente)) {
      try { await client.remove(e.name); } catch (err) {}
    }
  }

  // Subir renombrando patente_N.ext (conservando extensión original)
  let i = 0;
  for (const f of files) {
    i++;
    const ext = (f.name.includes('.') ? f.name.split('.').pop() : 'jpg').toLowerCase();
    const destName = patente + '_' + i + '.' + ext;
    const url = f['@microsoft.graph.downloadUrl'] || f['@content.downloadUrl'];
    if (!url) continue;
    const data = await this.helpers.httpRequest({ url, encoding: 'arraybuffer' });
    const buf = Buffer.isBuffer(data) ? data : Buffer.from(data);
    await client.uploadFrom(Readable.from(buf), destName);
    archivos.push(destName);
    markdownLines.push('![' + patente + '_' + i + '](' + cfg.publicBaseUrl + destName + ')');
  }
} finally {
  client.close();
}

if (archivos.length === 0) {
  return [{ json: { ok: false, accion: 'subir', patente, marca, total: 0, archivos: [], markdown: '', mensaje: 'No se pudo subir ninguna foto' } }];
}

return [{ json: { ok: true, accion: 'subir', patente, marca, total: archivos.length, archivos, markdown: markdownLines.join('\n') } }];

// FtpEliminar: borra del FTP todos los archivos que empiecen con la patente.
const ftpLib = require('basic-ftp');

const initJson = $('Init').item.json;
const cfg = initJson.cfg;
const patente = initJson.patente;

function norm(s) { return (s || '').toString().toUpperCase(); }

const client = new ftpLib.Client(30000);
client.ftp.verbose = false;
const eliminados = [];

try {
  await client.access({
    host: cfg.ftp.host,
    port: cfg.ftp.port,
    user: cfg.ftp.user,
    password: cfg.ftp.password,
    secure: cfg.ftp.secure,
    secureOptions: { rejectUnauthorized: false },
  });
  await client.cd(cfg.ftp.dir);

  const existentes = await client.list();
  for (const e of existentes) {
    if (e.isFile && norm(e.name).startsWith(patente)) {
      try { await client.remove(e.name); eliminados.push(e.name); } catch (err) {}
    }
  }
} finally {
  client.close();
}

const mensaje = eliminados.length
  ? ('Se eliminaron ' + eliminados.length + ' archivo(s) de la patente ' + patente)
  : 'No había fotos para la patente ' + patente;

return [{ json: { ok: true, accion: 'eliminar', patente, total: eliminados.length, eliminados, mensaje } }];
